/** Proper Energy Operations Studio — interactive presentation demo; no inverter connection. */
(() => {
'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const STORAGE='proper-energy-ops-demo-v3', SESSION='proper-energy-ops-session';
const NAV={overview:'Ringkasan',fleet:'Armada & Lokasi',energy:'Aliran Daya Langsung',alerts:'Alarm & Insiden',orders:'Perintah Kerja',analytics:'Analitik Energi',customers:'Layanan Pelanggan',finance:'Pusat Keuangan',reports:'Laporan & Ekspor',copilot:'Laboratorium AI',settings:'Pengaturan & Audit'};
const USER=[{id:'owner',name:'Manajemen Proper Energy',email:'owner@properenergy.local',role:'owner',display:'Owner / Manajemen'},{id:'operator',name:'Operator Monitoring',email:'operator@properenergy.local',role:'operator',display:'Operator / NOC'},{id:'teknisi',name:'Teknisi Lapangan',email:'teknisi@properenergy.local',role:'technician',display:'Teknisi / Field Service'},{id:'finance',name:'Finance Proper Energy',email:'finance@properenergy.local',role:'finance',display:'Finance / Administrasi'}];
const S={data:null,user:null,mode:'browser',view:'overview',siteId:'SITE-001',period:'week',hour:'siang',search:'',status:'all',severity:'all',tour:0,chat:[],energyChart:'week'};
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=n=>Number(n||0).toLocaleString('id-ID',{maximumFractionDigits:1});
const money=n=>'Rp '+Math.round(Number(n)||0).toLocaleString('id-ID');
const date=x=>{if(!x)return '—';const d=new Date(x);return Number.isNaN(d.getTime())?'—':d.toLocaleDateString('id-ID',{day:'2-digit',month:'short',year:'numeric'});};
const datetime=x=>{if(!x)return '—';const d=new Date(x);return Number.isNaN(d.getTime())?'—':d.toLocaleString('id-ID',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'});};
const ago=x=>{if(!x)return'—';let n=Math.round((Date.now()-new Date(x).getTime())/60000);return n<0?'Baru dijadwalkan':n<1?'Baru saja':n<60?n+' menit lalu':n<1440?Math.floor(n/60)+' jam lalu':Math.floor(n/1440)+' hari lalu';};
const status=(val)=>({healthy:'Optimal',warning:'Perlu perhatian',offline:'Offline',critical:'Kritis',high:'Tinggi',medium:'Sedang',low:'Rendah',open:'Baru',acknowledged:'Ditangani',resolved:'Selesai',scheduled:'Terjadwal',in_progress:'Dikerjakan',completed:'Selesai',cancelled:'Dibatalkan',paid:'Lunas',outstanding:'Belum dibayar',overdue:'Terlambat',normal:'Normal'}[val]||val);
const badge=(val)=>`<span class="status-pill ${esc(val)}">${esc(status(val))}</span>`;
const sum=(arr,fn)=>arr.reduce((s,v)=>s+Number(fn(v)||0),0);
const site=id=>S.data?.sites.find(x=>x.id===id);
const customer=id=>S.data?.customers.find(x=>x.id===id);
const can=(...roles)=>S.user&&roles.includes(S.user.role);
const rand=(i,j)=>Math.max(0.08,0.58+Math.sin((i+4)*1.7+j*.73)*.24+Math.cos(i*.6+j)*.11);
const out=(str)=>esc(str);
function makeSeed(){
 const samples=[['Bintaro Residence','Bintaro, Tangerang Selatan','Deye','SUN-8K-SG01',8,6.3,29.4,'healthy',78,93],['BSD Green Cove','BSD City, Tangerang Selatan','Solis','S6-EH1P',6,4.2,21.8,'warning',65,83],['Pondok Indah Estate','Pondok Indah, Jakarta Selatan','Huawei','SUN2000-8KTL',8,6.8,32.2,'healthy',null,96],['Alam Sutera Signature','Alam Sutera, Tangerang','GoodWe','GW6000-EH',6,4.5,20.1,'healthy',83,92],['Kebayoran Residence','Kebayoran Baru, Jakarta Selatan','Sungrow','SH6.0RS',6,4.9,25.4,'healthy',72,91],['Serpong Garden','Serpong, Tangerang Selatan','Deye','SUN-6K-SG03',6,0,0,'offline',61,null],['Ciputat Green House','Ciputat, Tangerang Selatan','Solis','S5-GR1P',5,4.1,18.5,'healthy',null,89],['Graha Raya Residence','Graha Raya, Tangerang','Growatt','MIN 6000TL-X',6,4.7,21.3,'healthy',null,90],['Bintaro Sektor 7','Bintaro, Tangerang Selatan','Deye','SUN-5K-SG03',5,3.7,16.5,'warning',86,79],['Kemang Home Solar','Kemang, Jakarta Selatan','Solis','S6-EH1P',5,4.1,17.6,'healthy',73,91],['Cilandak Residence','Cilandak, Jakarta Selatan','Huawei','SUN2000-6KTL',6,4.8,22.7,'healthy',null,94],['Lebak Bulus Home','Lebak Bulus, Jakarta Selatan','Deye','SUN-8K-SG01',8,5.9,30.2,'healthy',85,92],['Gading Serpong Home','Gading Serpong, Tangerang','Sungrow','SH8.0RS',8,6.1,27.2,'warning',80,82],['Bintaro Emerald','Bintaro, Tangerang Selatan','GoodWe','GW5000-ES',5,3.9,19.2,'healthy',74,92],['BSD The Green','BSD City, Tangerang Selatan','Solis','S6-GR1P',5,4.2,19.4,'healthy',null,90],['Permata Hijau Roof','Permata Hijau, Jakarta Selatan','Deye','SUN-6K-SG03',6,4.4,22.1,'healthy',81,88]];
 const ds=(add,h=9)=>{const x=new Date();x.setDate(x.getDate()+add);x.setHours(h,0,0,0);return x.toISOString();};
 const sites=samples.map((p,i)=>({id:`SITE-${String(i+1).padStart(3,'0')}`,name:p[0],location:p[1],vendor:p[2],model:p[3],capacityKw:p[4],powerKw:p[5],energyTodayKwh:p[6],status:p[7],batteryPct:p[8],performancePct:p[9],customerId:`CUS-${String(i+1).padStart(3,'0')}`,installationDate:`2025-${String(i%12+1).padStart(2,'0')}-12`,serial:`DEMO-${10001+i}`,lastSeen:p[7]==='offline'?ds(-2,7):ds(0,12),tariffRp:1699,solarSelfUsePct:79+i%4*3,monthlyEnergyKwh:p[6]*24}));
 const customers=sites.map((s,i)=>({id:s.customerId,name:`Pelanggan Proper ${String(i+1).padStart(3,'0')}`,segment:i%5===0?'Bisnis':'Residensial',siteId:s.id,servicePlan:i%3===0?'Premium Care':'Standard Care',note:'',contact:'Tidak ditampilkan (demo)'}));
 const alerts=[['SITE-006','critical','Inverter tidak mengirim data','Gateway offline. Periksa jaringan dan portal resmi vendor.','open',-1],['SITE-002','high','Produksi di bawah ekspektasi','Yield gap simulasi 17%; verifikasi shading, cuaca dan sensor.','open',0],['SITE-009','high','Performa menurun','Tinjau panel, inverter dan histori produksi.','acknowledged',-1],['SITE-013','medium','Performance ratio perlu verifikasi','Deviasi pada skenario simulasi.','open',0],['SITE-001','low','Jadwal inspeksi rutin','Jadwal preventive maintenance mendekat.','acknowledged',-2],['SITE-004','low','Baterai mencapai 83%','Pemantauan normal; catatan demo.','resolved',-5]].map((a,i)=>({id:`INC-${String(i+1).padStart(4,'0')}`,siteId:a[0],severity:a[1],title:a[2],description:a[3],status:a[4],createdAt:ds(a[5],8+i),acknowledgedAt:a[4]==='acknowledged'?ds(-1):null,resolvedAt:a[4]==='resolved'?ds(-4):null,assignee:'operator@properenergy.local',resolutionNote:null}));
 const orders=[['SITE-006','Pemeriksaan gateway & jaringan','critical','in_progress',1],['SITE-002','Inspeksi bayangan dan permukaan modul','high','scheduled',2],['SITE-009','Pemeriksaan performa inverter','high','open',3],['SITE-001','Preventive maintenance triwulan','normal','completed',-1],['SITE-013','Validasi anomali output','normal','open',4]].map((a,i)=>({id:`WO-${i+1001}`,siteId:a[0],title:a[1],priority:a[2],status:a[3],assignee:'teknisi@properenergy.local',createdAt:ds(-2),dueAt:ds(a[4],16),notes:'Work order simulasi.',resolution:a[3]==='completed'?'Inspeksi rutin selesai.':null,completedAt:a[3]==='completed'?ds(-1):null,incidentId:i<3?alerts[i].id:null}));
 const invoices=sites.slice(0,9).map((s,i)=>({id:`INV-${202610001+i}`,customerId:s.customerId,siteId:s.id,description:i%2?'Preventive maintenance':'Paket after-sales',amountRp:250000+i%4*150000,status:['paid','outstanding','paid','overdue','outstanding','paid','paid','overdue','outstanding'][i],dueAt:ds(i-3),issuedAt:ds(-25)}));
 return {version:3,sites,customers,alerts,orders,invoices,notes:[],activity:[{id:'ACT-1',who:'system',action:'DEMO_SEEDED',entity:'system',description:'Dataset simulasi dibuat',time:new Date().toISOString()}],settings:{tariffRp:1699,monthlyOmRp:250000,alertSlaCriticalMin:15,company:'Proper Energy Indonesia',demo:true}};
}
function localDB(){try{let s=JSON.parse(localStorage.getItem(STORAGE)||'null');if(s&&s.version===3)return s;}catch{}let db=makeSeed();localStorage.setItem(STORAGE,JSON.stringify(db));return db;}
function persist(){if(S.mode==='browser'&&S.data)localStorage.setItem(STORAGE,JSON.stringify(S.data));}
function addAudit(action,entity,description){S.data.activity.unshift({id:'ACT-'+Date.now(),who:S.user?.email||'demo',action,entity,description,time:new Date().toISOString()});}
function uid(prefix,rows){return prefix+'-'+String(Math.max(0,...rows.map(x=>Number(x.id.split('-').at(-1))||0))+1).padStart(4,'0');}
async function probe(){try{const controller=new AbortController();const to=setTimeout(()=>controller.abort(),1500);const r=await fetch('/ops-api/status',{signal:controller.signal,cache:'no-store'});clearTimeout(to);if(r.ok && (await r.json()).mode==='local-demo')S.mode='local';}catch{S.mode='browser';}}
async function api(endpoint,{method='GET',body}={}){
 if(S.mode==='local'){const r=await fetch('/ops-api/'+endpoint,{method,headers:{...(body?{'Content-Type':'application/json'}:{})},body:body?JSON.stringify(body):undefined,credentials:'same-origin'});let j=await r.json();if(!r.ok||j.ok===false)throw new Error(j.error||'Gagal mengakses server lokal.');return j;}
 return browserApi(endpoint,method,body);
}
function browserApi(endpoint,method,body={}){
 const u=USER.find(x=>x.email===sessionStorage.getItem(SESSION));const err=(message)=>{throw new Error(message);};
 if(endpoint==='login'){if(body.password!=='Demo123!')return err('Password demo tidak cocok.');const user=USER.find(x=>x.email===body.email);if(!user)return err('Akun demo tidak dikenal.');sessionStorage.setItem(SESSION,user.email);return {ok:true,user};}
 if(endpoint==='me'){if(!u)return err('Belum login');return {ok:true,user:u};}
 if(endpoint==='logout'){sessionStorage.removeItem(SESSION);return {ok:true};}
 if(!u)return err('Sesi demo tidak aktif.');
 const db=S.data||localDB();const permit=(roles)=>{if(!roles.includes(u.role))err('Peran Anda tidak diizinkan untuk tindakan ini.');};
 if(endpoint==='bootstrap')return {ok:true,user:u,data:db,meta:{mode:'simulated-browser',source:'localStorage',live:false,integrations:[]}};
 if(endpoint==='insights')return {ok:true,answer:insight(body.question,db)};
 if(endpoint==='alerts/simulate'){permit(['owner','operator']);const s=db.sites.find(x=>x.id===body.siteId);if(!s)err('Lokasi tidak ditemukan.');const item={id:uid('INC',db.alerts),siteId:s.id,severity:'critical',title:'Simulasi konektivitas terputus',description:'Skenario demo; bukan notifikasi inverter sesungguhnya.',status:'open',createdAt:new Date().toISOString(),acknowledgedAt:null,resolvedAt:null,resolutionNote:null,assignee:u.email};db.alerts.unshift(item);addAudit('SIMULATE_ALERT',item.id,item.title);persist();return {ok:true,item};}
 let m=endpoint.match(/^alerts\/(INC-\d+)\/(ack|resolve)$/);if(m){permit(['owner','operator','technician']);const item=db.alerts.find(x=>x.id===m[1]);if(!item)err('Insiden tidak ditemukan');if(m[2]==='ack'){item.status='acknowledged';item.assignee=u.email;item.acknowledgedAt=new Date().toISOString();}else{if(!body.note?.trim())err('Catatan penyelesaian wajib diisi');item.status='resolved';item.resolvedAt=new Date().toISOString();item.resolutionNote=String(body.note).slice(0,320);}addAudit(m[2]==='ack'?'ACK_ALERT':'RESOLVE_ALERT',item.id,item.title);persist();return {ok:true,item};}
 if(endpoint==='orders'&&method==='POST'){permit(['owner','operator','technician']);if(!body.title?.trim()||!db.sites.some(x=>x.id===body.siteId))err('Lokasi dan judul diperlukan');const item={id:uid('WO',db.orders),siteId:body.siteId,title:String(body.title).slice(0,140),priority:body.priority||'normal',status:'open',assignee:body.assignee||u.email,createdAt:new Date().toISOString(),dueAt:body.dueAt||new Date(Date.now()+86400000).toISOString(),notes:body.notes||'',resolution:null,completedAt:null,incidentId:body.incidentId||null};db.orders.unshift(item);addAudit('CREATE_WO',item.id,item.title);persist();return {ok:true,item};}
 m=endpoint.match(/^orders\/(WO-\d+)$/);if(m){permit(['owner','operator','technician']);const item=db.orders.find(x=>x.id===m[1]);if(!item)err('Tugas tidak ditemukan');if(body.status==='completed'&&!body.resolution?.trim())err('Catatan hasil wajib diisi.');if(!['open','scheduled','in_progress','completed','cancelled'].includes(body.status))err('Status tidak valid');item.status=body.status;if(body.status==='completed'){item.completedAt=new Date().toISOString();item.resolution=body.resolution;}addAudit('UPDATE_WO',item.id,item.status);persist();return {ok:true,item};}
 m=endpoint.match(/^customers\/(CUS-\d+)\/note$/);if(m){permit(['owner','operator','finance']);if(!body.note?.trim())err('Isi catatan pelanggan');const item={id:'NOTE-'+Date.now(),customerId:m[1],body:String(body.note).slice(0,800),by:u.email,createdAt:new Date().toISOString()};db.notes.unshift(item);addAudit('ADD_CUSTOMER_NOTE',m[1],item.body);persist();return {ok:true,item};}
 m=endpoint.match(/^invoices\/(INV-\d+)$/);if(m){permit(['owner','finance']);const item=db.invoices.find(x=>x.id===m[1]);if(!item)err('Invoice tidak ditemukan');if(!['paid','outstanding','overdue'].includes(body.status))err('Status tidak valid');item.status=body.status;addAudit('UPDATE_INVOICE',item.id,item.status);persist();return{ok:true,item};}
 if(endpoint==='settings'){permit(['owner']);for(const k of ['tariffRp','monthlyOmRp','alertSlaCriticalMin'])if(!Number.isFinite(Number(body[k]))||Number(body[k])<0)err('Angka tidak valid');Object.assign(db.settings,{tariffRp:Number(body.tariffRp),monthlyOmRp:Number(body.monthlyOmRp),alertSlaCriticalMin:Number(body.alertSlaCriticalMin)});addAudit('UPDATE_SETTINGS','settings','Asumsi demo diperbarui');persist();return {ok:true};}
 if(endpoint==='reset'){permit(['owner']);S.data=makeSeed();persist();return {ok:true};}
 return err('Aksi tidak tersedia dalam mode demo browser.');
}
function insight(question,db){const q=String(question||'').toLowerCase(),broken=db.alerts.filter(a=>a.status!=='resolved'),offline=db.sites.filter(s=>s.status==='offline');if(/offline|mati|putus|koneksi/.test(q))return {title:'Pengecekan konektivitas',text:`Ada ${offline.length} lokasi berstatus offline pada dataset demo: ${offline.map(s=>s.name).join(', ')||'tidak ada'}. Periksa logger, jaringan, daya inverter, dan portal vendor sebelum menyimpulkan kerusakan.`,next:'Buka Fleet → lokasi offline → buat Work Order.',confidence:'Aturan lokal — bukan diagnosis AI'};if(/alarm|prioritas|insiden|masalah/.test(q))return {title:'Prioritas operator',text:`Ada ${broken.length} insiden aktif dan ${broken.filter(a=>a.severity==='critical').length} insiden kritis. Dahulukan lokasi tanpa telemetri, lalu gap produksi. Catat PIC dan bukti pemeriksaan.`,next:'Buka Insiden, acknowledge, lalu buat work order.',confidence:'Aturan deterministik atas data simulasi'};if(/hemat|rupiah|biaya|finance|tagihan/.test(q))return {title:'Estimasi bukan tagihan PLN',text:`Estimasi energi harian ${fmt(sum(db.sites,s=>s.energyTodayKwh))} kWh. Hitung penghematan dari energi self-consumption × tarif yang sesuai; produksi total bukan otomatis pengurangan tagihan.`,next:'Atur tarif dan penggunaan sendiri di Finance center.',confidence:'Perhitungan demo'};if(/baterai|soc|backup/.test(q))return{title:'Evaluasi kapasitas baterai',text:'Perkiraan cadangan perlu SOC, kapasitas usable, beban kritis, efisiensi inverter dan batas discharge. Sistem tanpa baterai harus ditampilkan N/A.',next:'Buka energy flow dan pilih lokasi hybrid.',confidence:'Panduan teknis umum'};return {title:'Ringkasan operasi',text:`Ada ${db.sites.length} lokasi simulasi dan ${broken.length} insiden aktif. Prioritaskan keputusan manusia: temukan masalah, tentukan PIC, kerjakan, lalu verifikasi hasil dan dampak finansial.`,next:'Coba: “lokasi mana offline?”, “prioritas alarm?”, atau “berapa hemat?”.',confidence:'Ringkasan lokal, tanpa koneksi model AI'};}
async function sync(){const res=await api('bootstrap');S.data=res.data;S.user=res.user;document.getElementById('side-user-name').textContent=S.user.name;document.getElementById('side-user-role').textContent=S.user.display;document.getElementById('nav-sites').textContent=S.data.sites.length;document.getElementById('nav-alerts').textContent=S.data.alerts.filter(a=>a.status!=='resolved').length;$('#auth-screen').hidden=true;render();}
function toast(message,err=false){const el=document.createElement('div');el.className='toast'+(err?' error':'');el.textContent=message;$('#toast-region').append(el);setTimeout(()=>el.remove(),4200);}
async function act(fn,success){try{await fn();if(success)toast(success);await sync();}catch(e){toast(e.message||'Aksi gagal',true);}}
function page(title,sub='',actions=''){return `<div class="page-top"><div><div class="section-overline">OPERASIONAL SURYA / ${esc(NAV[S.view].toUpperCase())}</div><h1 style="margin-top:9px">${title}</h1><p>${sub}</p></div><div class="page-actions">${actions}</div></div>`;}
function demoBar(){return `<div class="demo-bar"><span><b>● Ruang Simulasi Demo</b> · ${S.mode==='local'?'Data tersimpan di server lokal':'Data tersimpan di browser ini'}. Tidak terhubung ke perangkat fisik maupun rekening PLN.</span><span>2026 · Proper Energy</span></div>`;}
function stat(label,value,unit,foot,icon='↗'){return `<article class="stat-card"><div class="kpi-label"><span>${label}</span><span class="kpi-icon">${icon}</span></div><div class="metric-value">${value}${unit?` <small>${unit}</small>`:''}</div><p>${foot}</p></article>`;}
function section(title,desc='',actions=''){return `<div class="panel-head"><div><h3>${title}</h3><p>${desc}</p></div>${actions}</div>`;}
function side(s){return `<div><span class="table-primary">${esc(s.name)}</span><div class="table-sub">${esc(s.location)}</div></div>`;}
function alertsActive(){return S.data.alerts.filter(a=>a.status!=='resolved');}
function selectSite(val=''){return `<select class="select" id="site-picker" aria-label="Pilih lokasi">${S.data.sites.map(s=>`<option value="${s.id}" ${s.id===(val||S.siteId)?'selected':''}>${esc(s.name)} · ${esc(s.vendor)}</option>`).join('')}</select>`;}
function siteOptions(selected=''){return S.data.sites.map(s=>`<option value="${s.id}" ${s.id===selected?'selected':''}>${esc(s.name)}</option>`).join('');}
function chartLine(values,maxW=700,high=225,ref=[]){const max=Math.max(1,...values,...ref)*1.15,pad=16,n=values.length,px=i=>pad+(maxW-2*pad)*(i/Math.max(1,n-1)),py=v=>high-28-(v/max)*(high-62);const grid=[0,.25,.5,.75,1].map(t=>`<line x1="${pad}" y1="${py(max*t)}" x2="${maxW-pad}" y2="${py(max*t)}" stroke="#e4ebe2" stroke-dasharray="3 5"/><text x="0" y="${py(max*t)+3}" fill="#99aa9c" font-size="9">${Math.round(max*t)}</text>`).join('');const pts=values.map((v,i)=>`${px(i)},${py(v)}`).join(' '),fill=`${pad},${high-28} ${pts} ${maxW-pad},${high-28}`;const refLine=ref.length?`<polyline points="${ref.map((v,i)=>`${px(i)},${py(v)}`).join(' ')}" fill="none" stroke="#b1c3a4" stroke-width="2" stroke-dasharray="6 5"/>`:'';return `<div class="chart-wrap"><svg role="img" aria-label="Grafik energi simulasi: ${values.map(x=>fmt(x)).join(', ')}" viewBox="-5 0 ${maxW+12} ${high+5}" preserveAspectRatio="none" style="height:225px">${grid}<polygon points="${fill}" fill="#589269" opacity=".09"/>${refLine}<polyline points="${pts}" stroke="#477855" fill="none" stroke-width="3.3" stroke-linecap="round" stroke-linejoin="round"/>${values.map((v,i)=>`<circle cx="${px(i)}" cy="${py(v)}" r="3.2" fill="#477855" stroke="#fff" stroke-width="1.5"><title>${fmt(v)} kWh (simulasi)</title></circle>`).join('')}</svg></div>`;}
function overview(){const db=S.data,a=alertsActive(),power=sum(db.sites,s=>s.powerKw),cap=sum(db.sites,s=>s.capacityKw),yieldK=sum(db.sites,s=>s.energyTodayKwh),healthy=db.sites.filter(s=>s.status==='healthy').length,critical=a.filter(x=>x.severity==='critical').length,arr=Array.from({length:12},(_,i)=>Math.round((20+10*i+9*Math.sin(i*1.4))*rand(i,1))),reference=arr.map((v,i)=>v*(1.06+.05*Math.cos(i)));
 return demoBar()+`<section class="hero"><div><div class="eyebrow">● SELAMAT DATANG DI PROPER ENERGY</div><h1>Mentari Menyinari,<br/><em>Aman Terkendali.</em></h1><p>Satu pandangan terpadu untuk memantau seluruh instalasi surya, mendeteksi kebutuhan perbaikan, dan memastikan mutu layanan purnajual terjaga prima.</p><div class="hero-quick"><button data-action="tour">Mulai Tur Terpandu ↗</button><button data-view="fleet">Jelajahi 16 Lokasi →</button></div></div><div class="hero-details"><div class="hero-summary"><div><div class="eyebrow">KAPASITAS ARMADA · DEMO</div><strong>${fmt(cap)} <small style="font:inherit;font-size:13px">kWp</small></strong><span>${db.sites.length} instalasi di Jabodetabek</span></div><span class="bubble">${Math.round(healthy/db.sites.length*100)}% optimal</span></div><div class="hero-lower"><div><small>Produksi energi hari ini</small><strong>${fmt(yieldK)} kWh</strong></div><div><small>Insiden kritis aktif</small><strong>${critical} <span style="font-size:10px;color:#b8ceaa">butuh tindakan</span></strong></div></div></div></section>
 <section class="stats-grid">${stat('Daya sesaat armada',fmt(power),'kW','Total keluaran daya sesaat portofolio demo','ϟ')}${stat('Produksi hari ini',fmt(yieldK),'kWh','Akumulasi energi bersih seluruh lokasi','↗')}${stat('Instalasi sehat',`${healthy} / ${db.sites.length}`,'',`${db.sites.filter(s=>s.status==='warning').length} perlu perhatian · ${db.sites.filter(s=>s.status==='offline').length} offline`,'✓')}${stat('Insiden butuh respons',a.length,'',`${critical} kritis · diurutkan berdasar urgensi`,'!')}</section>
 <div class="dashboard-cols"><section class="panel">${section('Tren Produksi Energi','Grafik simulasi sintetis untuk demonstrasi operasional.',`<button data-view="analytics" class="btn">Buka Analitik ↗</button>`)}${chartLine(arr,700,225,reference)}<div class="chart-caption"><span><i></i>Produksi simulasi</span><span><i></i>Garis acuan standar</span><span>Periode 12 titik pantau</span></div></section><section class="panel">${section('Prioritas Tindakan Operator','Daftar insiden teratas yang membutuhkan verifikasi teknisi.',`<button data-view="alerts" class="btn">Lihat Semua ↗</button>`)}<div class="priority-list">${a.slice(0,4).map(x=>`<div class="priority-item"><i class="severity-dot ${x.severity}"></i><div class="priority-item-main"><b>${esc(x.title)}</b><p>${esc(site(x.siteId)?.name)} · ${status(x.severity)} · ${ago(x.createdAt)}</p></div><button data-action="alert-detail" data-id="${x.id}">Detail ↗</button></div>`).join('')}</div></section></div>
 <div class="section-grid"><section class="panel">${section('Ringkasan Armada Pilihan','Kondisi operasional inverter pada lokasi terpilih.',`<button data-view="fleet" class="btn">Semua Lokasi ↗</button>`)}${db.sites.slice(0,6).map(s=>`<div class="list-row"><div>${side(s)}</div><div style="display:flex;align-items:center;gap:12px">${badge(s.status)}<button data-action="site-detail" data-id="${s.id}" class="inline-link">↗</button></div></div>`).join('')}</section><section class="panel">${section('Kemajuan Penanganan Tim','Status penugasan teknisi lapangan yang sedang berjalan.',`<button data-view="orders" class="btn">Daftar Perintah Kerja ↗</button>`)}${db.orders.slice(0,5).map(x=>`<div class="list-row"><div><div class="lead">${esc(x.title)}</div><div class="secondary">${esc(site(x.siteId)?.name)} · ${date(x.dueAt)}</div></div>${badge(x.status)}</div>`).join('')}<div class="insight-line"><strong>Rekomendasi Langkah Operator</strong><p>Pilih salah satu insiden kritis, lakukan konfirmasi (acknowledge), terbitkan surat perintah kerja teknisi, lalu verifikasi catatan hasil perbaikannya.</p></div></section></div>`;
}
function fleet(){let rows=S.data.sites.filter(s=>(S.status==='all'||s.status===S.status)&&(!S.search||`${s.name} ${s.location} ${s.vendor} ${s.model}`.toLowerCase().includes(S.search.toLowerCase())));
 return demoBar()+page('Satu Layar Terpadu, Seluruh Lokasi Terpantau.','Pantau status seluruh logger, inverter, daya aktif, dan riwayat komunikasi perangkat surya.',`<button class="btn" data-action="export" data-scope="sites">↓ Ekspor Data Armada</button><button class="primary-btn" data-action="simulate">＋ Simulasi Gangguan</button>`)+`<section class="stats-grid">${stat('Total instalasi',S.data.sites.length,'lokasi','Seluruh aset surya terdaftar','▦')}${stat('Kondisi optimal',S.data.sites.filter(s=>s.status==='healthy').length,'','Bekerja prima tanpa kendala','✓')}${stat('Perlu perhatian',S.data.sites.filter(s=>s.status==='warning').length,'','Perlu pengecekan hasil produksi','△')}${stat('Status terputus',S.data.sites.filter(s=>s.status==='offline').length,'','Logger atau inverter tanpa sinyal','!')}</section><div class="panel"><div class="table-toolbar"><div class="filters"><input class="input search-input" type="search" data-filter="search" value="${esc(S.search)}" placeholder="Cari nama lokasi, merek inverter, atau wilayah..." aria-label="Cari lokasi"/><select class="select" data-filter="status" aria-label="Filter status"><option value="all">Semua status</option>${['healthy','warning','offline'].map(s=>`<option ${s===S.status?'selected':''} value="${s}">${status(s)}</option>`).join('')}</select></div><span class="muted-note">${rows.length} lokasi ditemukan</span></div><div class="table-wrap"><table><thead><tr><th>Lokasi / Wilayah</th><th>Merek & Model Inverter</th><th>Kapasitas DC</th><th>Daya Sesaat</th><th>Produksi Hari Ini</th><th>Status Operasi</th><th>Sinyal Terakhir</th><th>Tindakan</th></tr></thead><tbody>${rows.map(s=>`<tr><td>${side(s)}</td><td><div class="table-primary">${esc(s.vendor)}</div><div class="table-sub">${esc(s.model)}</div></td><td class="mono">${fmt(s.capacityKw)} kWp</td><td class="mono">${fmt(s.powerKw)} kW</td><td class="mono">${fmt(s.energyTodayKwh)} kWh</td><td>${badge(s.status)}</td><td>${ago(s.lastSeen)}</td><td><button class="inline-link" data-action="site-detail" data-id="${s.id}">Explore ↗</button></td></tr>`).join('')||'<tr><td colspan="8"><div class="empty"><strong>Tidak ada lokasi cocok.</strong><p>Coba kata kunci atau filter lain.</p></div></td></tr>'}</tbody></table></div></div>`;
}
function flow(){const s=site(S.siteId)||S.data.sites[0];let factor={pagi:.36,siang:1,sore:.22,malam:0}[S.hour],solar=(s.status==='offline'?0:s.powerKw*factor),load={pagi:2.3,siang:3.5,sore:4.1,malam:2.7}[S.hour],surplus=solar-load,hasBatt=s.batteryPct!==null,bat=0,grid=0,curtailed=0;if(hasBatt&&surplus>0&&s.batteryPct<96)bat=Math.min(surplus,2.2);if(hasBatt&&surplus<0&&s.batteryPct>20)bat=Math.max(surplus,-1.6);grid=load-solar+bat;if(grid<0){curtailed=-grid;grid=0;}const solarD=fmt(solar),loadD=fmt(load);return demoBar()+page('Jelajahi Aliran Daya Mandiri.','Simulasi interaktif keseimbangan energi: panel surya, inverter, beban hunian, baterai cadangan, dan jaringan PLN.',`<button data-action="site-detail" data-id="${s.id}" class="btn">Info Perangkat ↗</button>`)+`<div class="panel long-card"><div class="table-toolbar"><div class="filters"><span class="filter-label">Instalasi aktif</span>${selectSite(s.id)}</div><div class="seg-control" aria-label="Waktu simulasi">${[['pagi','08.00'],['siang','12.30'],['sore','16.30'],['malam','20.00']].map(([v,l])=>`<button data-hour="${v}" class="${S.hour===v?'active':''}">${l}</button>`).join('')}</div></div><div class="split-grid"><div class="flow-card"><div class="section-overline" style="color:#bce4a8;margin-bottom:15px">ALIRAN DAYA · ${S.hour.toUpperCase()} · SIMULASI</div><div class="flow-stage"><div class="energy-nodes"><div class="energy-node solar-node primary"><span class="node-icon">☼</span><small>Panel Surya · DC</small><strong>${solarD} kW</strong></div><div class="energy-node grid-node"><span class="node-icon">⌁</span><small>Jaringan PLN · Impor</small><strong>${fmt(grid)} kW</strong></div><div class="energy-node main-node"><span class="node-icon">ϟ</span><small>Inverter</small><strong>${esc(s.vendor)}</strong></div><div class="energy-node home-node"><span class="node-icon">⌂</span><small>Beban Rumah</small><strong>${loadD} kW</strong></div><div class="energy-node battery-node ${!hasBatt?'no-battery':''}"><span class="node-icon">▣</span><small>${hasBatt?'Battery '+s.batteryPct+'%':'No battery'}</small><strong>${hasBatt?`${bat>0?'+':''}${fmt(bat)} kW`:'N/A'}</strong></div></div></div><div class="flow-caption">Surya → Inverter → Beban Rumah · Ditopang Baterai & PLN</div><div class="energy-legend"><span>● <strong>Solar</strong> ${solarD} kW</span><span>● <strong>Import PLN</strong> ${fmt(grid)} kW</span><span>● <strong>Battery</strong> ${hasBatt?(bat>=0?'charging / idle':'discharging'):'not installed'}</span></div></div><div><section class="panel" style="margin-bottom:15px">${section('Live simulation telemetry','Nilai berubah ketika waktu atau lokasi diganti.')}<div class="list-row"><span>Installed capacity</span><strong class="mono">${fmt(s.capacityKw)} kWp</strong></div><div class="list-row"><span>Inverter / gateway</span><strong>${esc(s.vendor)} · ${esc(s.model)}</strong></div><div class="list-row"><span>Battery state of charge</span><strong class="mono">${hasBatt?s.batteryPct+'%':'Not installed'}</strong></div><div class="list-row"><span>Solar to load</span><strong class="mono">${fmt(Math.min(load,solar))} kW</strong></div><div class="list-row"><span>Grid import</span><strong class="mono">${fmt(grid)} kW</strong></div><div class="list-row"><span>Surplus / curtailment</span><strong class="mono">${fmt(curtailed)} kW</strong></div><div class="list-row"><span>Monitoring status</span>${badge(s.status)}</div></section><div class="warning-box">Perangkat nyata membutuhkan pembacaan sensor/vendor API, model inverter, batas ekspor dan perizinan teknis. Diagram ini hanya ilustrasi keseimbangan daya, bukan pengendalian inverter.</div></div></div></div><div class="section-grid"><section class="panel">${section('PV production profile','Perbandingan keluaran simulasi 12 titik waktu.')}${chartLine(Array.from({length:12},(_,i)=>s.powerKw*Math.max(0,Math.sin((i+1)/12*Math.PI))*rand(i,2)),700,205)}</section><section class="panel">${section('Operator interpretation','Hal-hal yang perlu diperiksa sebelum mengambil tindakan.')}<div class="insight-line"><strong>① Telemetry freshness</strong><p>Periksa waktu pembaruan terakhir. Status “offline” tidak boleh diartikan sebagai inverter rusak tanpa bukti tambahan.</p></div><div class="insight-line"><strong>② Battery availability</strong><p>Tampilkan N/A jika baterai tidak terpasang; jangan tampilkan SOC nol yang bisa disalahartikan.</p></div><div class="insight-line"><strong>③ Energy reconciliation</strong><p>Data impor, konsumsi, baterai dan produksi perlu konsisten secara matematis.</p></div></section></div>`;}
function alerts(){let items=S.data.alerts.filter(x=>S.severity==='all'||x.severity===S.severity);const order={critical:0,high:1,medium:2,low:3};items.sort((a,b)=>(a.status==='resolved')-(b.status==='resolved')||order[a.severity]-order[b.severity]);return demoBar()+page('Dari Peringatan Menjadi Tindakan Nyata.','Dari deteksi sinyal → triase operator → penugasan teknisi → verifikasi hasil penyelesaian.',`<button class="btn" data-action="export" data-scope="alerts">↓ Ekspor Insiden</button>${can('owner','operator')?'<button class="primary-btn" data-action="simulate">＋ Picu Alarm Simulasi</button>':''}`)+`<section class="stats-grid">${stat('Insiden terbuka',alertsActive().length,'','Membutuhkan tindak lanjut operator','!')}${stat('Tingkat kritis',alertsActive().filter(x=>x.severity==='critical').length,'','Prioritaskan verifikasi koneksi data','⚠')}${stat('Dikonfirmasi (Ack)',alertsActive().filter(x=>x.status==='acknowledged').length,'','Telah diterima dan ditangani PIC','✓')}${stat('Terselesaikan',S.data.alerts.filter(x=>x.status==='resolved').length,'','Catatan penanganan tersimpan rapi','↗')}</section><section class="panel"><div class="table-toolbar"><div class="filters"><label class="filter-label" for="severity-filter">Filter severity</label><select class="select" id="severity-filter" aria-label="Filter tingkat insiden"><option value="all">Semua prioritas</option>${['critical','high','medium','low'].map(s=>`<option value="${s}" ${S.severity===s?'selected':''}>${status(s)}</option>`).join('')}</select></div><span class="muted-note">${items.length} insiden dalam dataset demo</span></div><div class="table-wrap"><table><thead><tr><th>Prioritas</th><th>Insiden</th><th>Lokasi</th><th>Waktu dibuat</th><th>State</th><th>Tindakan</th></tr></thead><tbody>${items.map(a=>`<tr><td><span style="display:flex;gap:8px;align-items:center"><i class="severity-dot ${a.severity}" style="margin:0"></i>${status(a.severity)}</span></td><td><button class="table-link" data-action="alert-detail" data-id="${a.id}">${esc(a.title)}</button><div class="table-sub">${a.id}</div></td><td>${esc(site(a.siteId)?.name)}</td><td>${datetime(a.createdAt)}</td><td>${badge(a.status)}</td><td><button class="inline-link" data-action="alert-detail" data-id="${a.id}">Manage ↗</button></td></tr>`).join('')}</tbody></table></div></section><div class="section-grid"><div class="panel">${section('Operator SLA','Waktu response dihitung dari pembuatan hingga acknowledgment.')}<div class="metric-pair"><div><small>Target first response P1</small><b>${fmt(S.data.settings.alertSlaCriticalMin)} min</b></div><div><small>Target penyelesaian</small><b>Per case</b></div></div><div class="warning-box" style="margin-top:14px">Nilai SLA hanya target konfigurasi, bukan jaminan layanan. Belum menggunakan notifikasi otomatis lintas perangkat.</div></div><div class="panel">${section('Standard triage protocol','Pola kerja yang bisa diuji operator.')}<div class="timeline"><div class="timeline-item"><strong>1. Acknowledge incident</strong>Operator mengambil tanggung jawab.</div><div class="timeline-item"><strong>2. Verify original source</strong>Bandingkan dengan portal vendor dan sensor asli.</div><div class="timeline-item"><strong>3. Dispatch technician</strong>Buat work order dengan PIC, prioritas dan deadline.</div><div class="timeline-item"><strong>4. Close with evidence</strong>Isi catatan tindakan dan verifikasi hasil.</div></div></div></div>`;}
function orders(){const db=S.data,active=db.orders.filter(o=>!['completed','cancelled'].includes(o.status)),done=db.orders.filter(o=>o.status==='completed'),overdue=active.filter(o=>new Date(o.dueAt)<new Date()).length;return demoBar()+page('Perintah Kerja Nyata, Beres Tanpa Jeda.','Jadwalkan kunjungan teknisi, pantau kepatuhan SLA, dan tutup pekerjaan hanya jika ada bukti penanganan.',`<button class="btn" data-action="export" data-scope="orders">↓ Ekspor Perintah Kerja</button>${can('owner','operator','technician')?'<button data-action="new-order" class="primary-btn">＋ Buat Perintah Kerja</button>':''}`)+`<section class="stats-grid">${stat('Perintah kerja aktif',active.length,'','Dalam proses atau menunggu jadwal','▤')}${stat('Sedang dikerjakan',active.filter(o=>o.status==='in_progress').length,'','Teknisi berada di lokasi','ϟ')}${stat('Lewat tenggat',overdue,'','Perlu eskalasi segera','!')}${stat('Selesai tuntas',done.length,'','Lengkap dengan laporan hasil','✓')}</section><section class="panel">${section('All maintenance tasks','Status dapat dipindahkan sesuai alur operasional.')}<div class="table-wrap"><table><thead><tr><th>Work order</th><th>Lokasi</th><th>Priority</th><th>Assigned to</th><th>Due date</th><th>Status</th><th>Action</th></tr></thead><tbody>${db.orders.map(o=>`<tr><td><button class="table-link" data-action="order-detail" data-id="${o.id}">${esc(o.title)}</button><div class="table-sub">${o.id}</div></td><td>${esc(site(o.siteId)?.name)}</td><td>${badge(o.priority)}</td><td>${esc(o.assignee.split('@')[0])}</td><td>${date(o.dueAt)}</td><td>${badge(o.status)}</td><td><button class="inline-link" data-action="order-detail" data-id="${o.id}">Manage ↗</button></td></tr>`).join('')}</tbody></table></div></section><div class="section-grid"><section class="panel">${section('Maintenance backlog','Pekerjaan aktif berdasarkan skala prioritas.')}<div class="metric-pair"><div><small>Critical + High</small><b>${active.filter(o=>['critical','high'].includes(o.priority)).length}</b></div><div><small>Normal priority</small><b>${active.filter(o=>o.priority==='normal').length}</b></div></div><div class="insight-line"><strong>Technician-first interface</strong><p>Teknisi membutuhkan judul tugas, alamat area, deadline, tindakan dan hasil. Hindari grafik dekoratif saat berada di lapangan.</p></div></section><section class="panel">${section('Recent completion','Jejak hasil pekerjaan sebagai dasar laporan.')}<div class="timeline">${done.length?done.map(o=>`<div class="timeline-item"><strong>${esc(o.title)}</strong>${esc(o.resolution||'Pekerjaan selesai')} · ${date(o.completedAt)}</div>`).join(''):'<div class="timeline-item">Belum ada penyelesaian.</div>'}</div></section></div>`;}
function analytics(){const db=S.data,k=sum(db.sites,s=>s.energyTodayKwh),periods={day:['Hari ini',12],week:['7 hari',7],month:['30 hari',30]},pr=periods[S.period]||periods.week,values=Array.from({length:pr[1]},(_,i)=>S.period==='day'?Math.round(k/5*Math.max(0,Math.sin(i/11*Math.PI))*rand(i,4)):Math.round(k*rand(i,2))),baseline=values.map((v,i)=>v*(1.04+.1*Math.sin(i+1))),sumVal=sum(values,x=>x),ratio=sum(values,(x,i)=>x)/sum(baseline,x=>x)*100;return demoBar()+page('Performance, explained.','Ubah periode untuk membaca tren contoh energi dan membandingkan performa dengan baseline simulasi.',`<button class="btn" data-action="export" data-scope="sites">↓ Export source data</button>`)+`<div class="panel long-card"><div class="table-toolbar"><div><div class="section-overline">ENERGY INTELLIGENCE</div><h2 style="margin-top:8px">${pr[0]} · simulated generation</h2></div><div class="seg-control">${[['day','Hari ini'],['week','7 hari'],['month','30 hari']].map(([k,l])=>`<button data-period="${k}" class="${S.period===k?'active':''}">${l}</button>`).join('')}</div></div><div class="stats-grid" style="margin-top:0">${stat('Total output',fmt(sumVal),'kWh','Energi dalam rentang simulasi','↗')}${stat('Baseline ratio',fmt(ratio)+'%','','Bukan performance ratio standar IEC','⇄')}${stat('Installed power',fmt(sum(db.sites,x=>x.capacityKw)),'kWp','Kapasitas portofolio','☼')}${stat('Active sites',db.sites.filter(s=>s.status!=='offline').length,'','Lokasi dengan komunikasi normal/perhatian','✓')}</div>${chartLine(values,900,280,baseline)}<div class="chart-caption"><span><i></i>Production, scenario</span><span><i></i>Expected baseline, synthetic</span><span>Nilai tidak berasal dari pengukuran lapangan</span></div></div><div class="section-grid"><section class="panel">${section('Performance by location','Rangking berbasis persentase performa data demo.')}<div>${db.sites.filter(s=>s.performancePct!==null).sort((a,b)=>a.performancePct-b.performancePct).slice(0,7).map(s=>`<div class="list-row"><div style="width:160px"><div class="lead">${esc(s.name)}</div><div class="secondary">${esc(s.vendor)}</div></div><div style="flex:1"><div class="meter"><span style="width:${s.performancePct}%"></span></div></div><b class="mono">${s.performancePct}%</b></div>`).join('')}</div></section><section class="panel">${section('Data quality checklist','Prioritas menuju performa analitik yang benar-benar dapat dipercaya.')}<div class="timeline"><div class="timeline-item"><strong>Raw telemetry</strong>timestamp dan timezone, meter PV, baterai, impor grid, tegangan, frekuensi.</div><div class="timeline-item"><strong>Sensor integrity</strong>Kalibrasi sensor, nilai hilang, deduplikasi, pengukuran yang tidak konsisten.</div><div class="timeline-item"><strong>Forecast validation</strong>Bandingkan aktual vs prediksi dengan MAE/MAPE dan interval ketidakpastian.</div><div class="timeline-item"><strong>Human acceptance</strong>Operator mengerti arti alarm tanpa perlu membaca manual panjang.</div></div></section></div>`;}
function customers(){const db=S.data;return demoBar()+page('After-sales feels personal.','Memperlihatkan hubungan pelanggan dengan instalasi, paket layanan dan catatan tindak lanjut; identitas pelanggan adalah placeholder.',`<button data-action="export" data-scope="customers" class="btn">↓ Export customer registry</button>`)+`<section class="stats-grid">${stat('Customer accounts',db.customers.length,'','Pelanggan contoh','◎')}${stat('Premium care',db.customers.filter(c=>c.servicePlan==='Premium Care').length,'','Rencana layanan premium','◇')}${stat('Open care cases',alertsActive().length,'','Insiden aktif di portofolio','!')}${stat('Follow-up notes',db.notes.length,'','Catatan aktivitas manual','✎')}</section><section class="panel">${section('Customer & asset registry','Seluruh informasi pelanggan dibatasi ke data simulasi.')}<div class="table-wrap"><table><thead><tr><th>Customer</th><th>Installation</th><th>Segment</th><th>Service plan</th><th>Active alerts</th><th>Action</th></tr></thead><tbody>${db.customers.map(c=>`<tr><td><div class="table-primary">${esc(c.name)}</div><div class="table-sub">${c.id}</div></td><td>${esc(site(c.siteId)?.name)}</td><td>${esc(c.segment)}</td><td><span class="tag">${esc(c.servicePlan)}</span></td><td>${db.alerts.filter(a=>a.siteId===c.siteId&&a.status!=='resolved').length}</td><td><button class="inline-link" data-action="customer-detail" data-id="${c.id}">Open account ↗</button></td></tr>`).join('')}</tbody></table></div></section><div class="section-grid"><section class="panel">${section('Customer promise','Layanan purna jual yang bisa dibuktikan.')}<div class="insight-line"><strong>Transparent monitoring</strong><p>Jelaskan status instalasi, batasan telemetri dan estimasi penghematan dengan bahasa yang dipahami pelanggan.</p></div><div class="insight-line"><strong>Documented follow-up</strong><p>Setiap insiden sebaiknya memiliki penanggung jawab, timestamp, dan bukti penyelesaian.</p></div></section><section class="panel">${section('Recent customer notes','Jejak komunikasi manual pada dashboard demo.')}${db.notes.length?db.notes.slice(0,5).map(n=>`<div class="list-row"><div class="lead">${esc(customer(n.customerId)?.name)}<div class="secondary">${esc(n.body)} · ${date(n.createdAt)}</div></div></div>`).join(''):'<div class="empty"><strong>Belum ada catatan.</strong><p>Buka profil pelanggan untuk menambahkan catatan demo.</p></div>'}</section></div>`;}
function finance(){const db=S.data,t=db.settings.tariffRp,monthlyKwh=sum(db.sites,s=>s.monthlyEnergyKwh),use=.82,gross=monthlyKwh*use*t,net=gross-db.settings.monthlyOmRp,paid=sum(db.invoices.filter(x=>x.status==='paid'),i=>i.amountRp),outstanding=sum(db.invoices.filter(x=>x.status!=='paid'),i=>i.amountRp);return demoBar()+page('Tiap Kilowatt Bernilai, Keuangan Rapi Terangkai.','Estimasi penghematan berbasis konsumsi mandiri; bukan tagihan resmi PLN dan bukan laporan laba rugi korporasi.',`<button data-action="export" data-scope="invoices" class="btn">↓ Ekspor Tagihan</button>`)+`<section class="stats-grid">${stat('Estimasi hemat kotor',money(gross),'','Energi terpakai mandiri × tarif asumsi','Rp')}${stat('Manfaat energi bersih',money(net),'','Setelah dikurangi biaya O&M bulanan','↗')}${stat('Tagihan tertagih',money(paid),'','Penerimaan jasa layanan purnajual','✓')}${stat('Menunggu pembayaran',money(outstanding),'','Total tagihan layanan belum lunas','!')}</section><div class="split-grid"><section class="panel">${section('Savings simulator','Ubah asumsi dan lihat dampaknya secara langsung; tidak mengubah invoice.')}<form id="finance-form"><div class="form-grid"><div class="form-field"><label for="fin-tariff">Tarif listrik asumsi (Rp/kWh)</label><input id="fin-tariff" class="input" name="tariff" type="number" min="0" max="20000" value="${t}" required></div><div class="form-field"><label for="fin-self">Self-consumption rate (%)</label><input id="fin-self" class="input" name="self" type="number" min="0" max="100" value="82" required></div><div class="form-field"><label for="fin-cost">O&M bulanan (Rp)</label><input id="fin-cost" class="input" name="cost" type="number" min="0" value="${db.settings.monthlyOmRp}" required></div><div class="form-field"><label for="fin-capex">Investasi awal ilustratif (Rp)</label><input id="fin-capex" class="input" name="capex" type="number" min="0" value="140000000" required></div></div><div class="form-footer"><button class="primary-btn" type="submit">Hitung skenario ↗</button></div></form><div id="finance-results" class="insight-line"><strong>Simulasi awal</strong><p>Penghematan kotor ${money(gross)} / bulan. Estimasi manfaat energi setelah O&M ${money(net)} / bulan, sebelum faktor pembiayaan dan pajak.</p></div></section><section class="panel">${section('Where the number comes from','Asumsi hitungan, bukan nilai tagihan aktual.')}<div class="list-row"><span>Produksi tahunan ekuivalen</span><b class="mono">${fmt(monthlyKwh*12)} kWh</b></div><div class="list-row"><span>Produksi bulanan (synthetic)</span><b class="mono">${fmt(monthlyKwh)} kWh</b></div><div class="list-row"><span>Default self-consumption</span><b>82%</b></div><div class="list-row"><span>Assumed tariff</span><b>${money(t)} / kWh</b></div><div class="list-row"><span>O&M assumed</span><b>${money(db.settings.monthlyOmRp)}</b></div><div class="warning-box" style="margin-top:15px">Tidak semua kWh produksi otomatis mengurangi tagihan. Penghitungan nyata membutuhkan meter ekspor/impor, tarif per pelanggan, skema interkoneksi, dan data historis tervalidasi.</div></section></div><section class="panel" style="margin-top:15px">${section('Service billing ledger','Status invoice dapat diubah oleh Owner atau Finance dalam demo.')}<div class="table-wrap"><table><thead><tr><th>Invoice</th><th>Customer</th><th>Service</th><th>Amount</th><th>Due date</th><th>State</th><th>Action</th></tr></thead><tbody>${db.invoices.map(i=>`<tr><td class="table-primary mono">${i.id}</td><td>${esc(customer(i.customerId)?.name)}</td><td>${esc(i.description)}</td><td class="mono">${money(i.amountRp)}</td><td>${date(i.dueAt)}</td><td>${badge(i.status)}</td><td>${i.status!=='paid'&&can('owner','finance')?`<button class="inline-link" data-action="mark-paid" data-id="${i.id}">Mark paid ↗</button>`:'<span class="muted-note">—</span>'}</td></tr>`).join('')}</tbody></table></div></section>`;}
function reports(){const db=S.data;return demoBar()+page('Laporan Rapi, Rapat Pimpinan Lebih Percaya Diri.','Ekspor data operasional untuk bahan evaluasi tim, pelaporan manajemen, dan audit teknis.',`<button class="primary-btn" data-action="print">↧ Cetak Ringkasan</button>`)+`<div class="stats-grid">${stat('Locations',db.sites.length,'','Total lokasi simulasi','▦')}${stat('Incident records',db.alerts.length,'','Termasuk resolved','!')}${stat('Work orders',db.orders.length,'','Termasuk selesai','▤')}${stat('Billing records',db.invoices.length,'','Invoice contoh','Rp')}</div><div class="section-grid">${[['sites','Fleet & devices','Kapasitas, status, merek, output, last-seen'],['alerts','Incident register','Prioritas, status, timestamp dan catatan'],['orders','Technician work orders','PIC, tenggat, status dan penyelesaian'],['customers','Customer directory','Akun placeholder dan paket layanan'],['invoices','Service invoicing','Nilai dan status pembayaran demo'],['activity','Activity & audit trail','Riwayat tindakan pengguna demo']].map(([scope,title,desc])=>`<div class="scenario-card" style="background:white"><div class="scenario-index">↓</div><div style="flex:1"><strong>${title}</strong><p>${desc}</p></div><button data-action="export" data-scope="${scope}" class="btn">CSV ↗</button></div>`).join('')}</div><section class="panel" style="margin-top:15px">${section('Executive reporting summary','Narasi ini dapat digunakan dalam demo, bukan klaim hasil produksi nyata.')}<div class="quote-banner">Portofolio demo Proper Energy mencakup ${db.sites.length} instalasi dengan total kapasitas ${fmt(sum(db.sites,x=>x.capacityKw))} kWp. Ada ${alertsActive().length} insiden terbuka untuk ditindaklanjuti. Sistem menggabungkan tugas operator, teknisi, finance dan pelanggan dalam satu cockpit.</div><div class="chip-row"><button data-view="overview" class="chip">Overview ↗</button><button data-view="analytics" class="chip">Analytics ↗</button><button data-view="finance" class="chip">Financial assumptions ↗</button></div></section>`;}
function copilot(){const prompts=['Lokasi mana yang offline?','Apa prioritas alarm saat ini?','Bagaimana menghitung penghematan?','Bagaimana menilai kapasitas baterai?'];return demoBar()+page('Tanya Kapan Saja, Solusi Terbuka Nyata.','Asisten cerdas berbasis aturan deterministik atas dataset demo untuk membantu triase harian.',`<button data-view="alerts" class="btn">Buka Daftar Insiden ↗</button>`)+`<div class="dashboard-cols"><section class="panel">${section('Proper Energy · Insights lab','Jawaban dapat dijelaskan dan dapat ditelusuri ke dataset demo.')}<div id="chat-output" style="display:grid;gap:13px;min-height:260px;max-height:520px;overflow-y:auto;margin-bottom:15px">${S.chat.length?S.chat.map(m=>`<div class="insight-line" style="margin:0;${m.who==='user'?'background:#eff4e8;justify-self:end;max-width:85%':'background:#f8faf6'}"><strong>${m.who==='user'?'You':'Proper Energy · Rules Engine'}</strong><p>${esc(m.text)}</p>${m.next?`<p><b>Next step:</b> ${esc(m.next)}</p><div class="muted-note">${esc(m.confidence||'')}</div>`:''}</div>`).join(''):'<div class="empty"><strong>Start with a question.</strong><p>Contoh: “lokasi mana offline?” untuk melihat prioritas dari data simulasi.</p></div>'}</div><form id="chat-form" style="display:flex;gap:9px"><input id="chat-question" class="input" style="flex:1" name="question" maxlength="800" autocomplete="off" placeholder="Tanyakan masalah operasional PLTS..." required/><button type="submit" class="primary-btn">Send ↗</button></form><div class="chip-row">${prompts.map(q=>`<button class="chip" data-action="ask" data-question="${esc(q)}">${esc(q)}</button>`).join('')}</div></section><section class="panel">${section('From answer to action','Sistem yang baik membantu orang mengambil keputusan, bukan menggantikan verifikasi.')}<div class="timeline"><div class="timeline-item"><strong>Describe the problem</strong>Operator memasukkan pertanyaan mengenai lokasi, alarm atau biaya.</div><div class="timeline-item"><strong>Explain evidence</strong>Ringkasan menggunakan data demo yang dapat diperiksa pada tabel dan daftar insiden.</div><div class="timeline-item"><strong>Recommend next move</strong>Arahkan pengguna ke alur inspeksi, work order atau keuangan.</div><div class="timeline-item"><strong>Human verification</strong>Operator wajib memeriksa log vendor sebelum mengambil keputusan teknis.</div></div><div class="warning-box">AI production di masa mendatang memerlukan model, RAG atas manual inverter, audit prompt, izin data, evaluasi hallucination dan human-in-the-loop.</div></section></div>`;}
function settings(){const s=S.data.settings,owner=can('owner');return demoBar()+page('Ruang Kerja Transparan, Tata Kelola Aman.','Asumsi finansial, batas toleransi SLA, dan jejak audit perubahan dapat ditinjau kapan saja.',`<button data-action="export" data-scope="activity" class="btn">↓ Ekspor Jejak Audit</button>`)+`<div class="split-grid"><section class="panel">${section('Assumptions & controls','Hanya role Owner dapat memperbarui pengaturan demo.')}<form id="settings-form"><div class="form-grid"><div class="form-field"><label for="setting-tariff">Tarif default Rp/kWh</label><input id="setting-tariff" type="number" min="0" max="20000" class="input" name="tariffRp" value="${s.tariffRp}" ${owner?'':'disabled'} required></div><div class="form-field"><label for="setting-om">Monthly O&M estimate</label><input id="setting-om" type="number" min="0" max="999999999" class="input" name="monthlyOmRp" value="${s.monthlyOmRp}" ${owner?'':'disabled'} required></div><div class="form-field"><label for="setting-sla">P1 acknowledgment SLA (minutes)</label><input id="setting-sla" type="number" min="1" max="1440" class="input" name="alertSlaCriticalMin" value="${s.alertSlaCriticalMin}" ${owner?'':'disabled'} required></div></div><div class="form-footer"><button type="submit" class="primary-btn" ${owner?'':'disabled'}>Save assumptions ↗</button></div></form><div class="permissions">Current account: <b>${esc(S.user.display)}</b><br>Mode: ${S.mode==='local'?'loopback local server':'browser-local demo'} · live integrations: none.</div></section><section class="panel">${section('Demo lifecycle','Cara aman melakukan presentasi berulang.')}<div class="scenario-card" style="margin:15px 0"><div class="scenario-index">1</div><div><strong>Reset to initial state</strong><p>Kembalikan alarm, work order dan invoice ke skenario awal setelah sesi presentasi.</p></div></div><button data-action="reset" class="btn" ${owner?'':'disabled'}>↻ Reset demo dataset</button><div class="warning-box" style="margin-top:20px">Autentikasi browser-local adalah simulasi role, bukan login production. Jangan memasukkan data pelanggan asli. Server lokal hanya terbuka ke 127.0.0.1.</div><div style="margin-top:18px"><button data-action="logout" class="outline-btn">Log out of workspace ↗</button></div></section></div><section class="panel" style="margin-top:15px">${section('Audit trail','Siapa melakukan tindakan apa, dan kapan (pada data demo).')}<div class="table-wrap"><table><thead><tr><th>Timestamp</th><th>Actor</th><th>Event</th><th>Entity</th><th>Detail</th></tr></thead><tbody>${S.data.activity.slice(0,40).map(a=>`<tr><td>${datetime(a.time)}</td><td>${esc(a.who)}</td><td><span class="tag">${esc(a.action)}</span></td><td>${esc(a.entity)}</td><td>${esc(a.description)}</td></tr>`).join('')}</tbody></table></div></section>`;}
function render(){if(!S.data)return;const route=location.hash.replace('#','');if(NAV[route]&&S.view!==route)S.view=route;const views={overview,fleet,energy:flow,alerts,orders,analytics,customers,finance,reports,copilot,settings};$('#view-root').innerHTML=views[S.view]();$('#bread-current').textContent=NAV[S.view];$$('.nav-link').forEach(el=>{const active=el.dataset.view===S.view;el.classList.toggle('active',active);if(active)el.setAttribute('aria-current','page');else el.removeAttribute('aria-current');});$('#nav-alerts').textContent=alertsActive().length;$('#nav-sites').textContent=S.data.sites.length;document.title=NAV[S.view]+' · Proper Energy Operations Studio';}
function nav(view){if(!NAV[view])return;S.view=view;location.hash=view;$('#sidebar').classList.remove('open');$('#nav-backdrop').hidden=true;$('#mobile-menu').setAttribute('aria-expanded','false');render();window.scrollTo({top:0,behavior:'instant'});$('#view-root').focus({preventScroll:true});}
function openModal(title,body){$('#modal-title').textContent=title;$('#modal-content').innerHTML=body;$('#modal-backdrop').hidden=false;$('#modal-close').focus();}
function closeModal(){$('#modal-backdrop').hidden=true;$('#modal-content').innerHTML='';}
function alertDetail(id){const a=S.data.alerts.find(a=>a.id===id);if(!a)return toast('Insiden tidak ditemukan',true);const editable=can('owner','operator','technician');openModal(a.title,`<div class="modal-body"><p>${esc(a.description)}</p><div class="detail-grid"><div class="detail"><div class="detail-label">Priority</div>${badge(a.severity)}</div><div class="detail"><div class="detail-label">State</div>${badge(a.status)}</div><div class="detail"><div class="detail-label">Created</div><strong>${datetime(a.createdAt)}</strong></div></div><div class="list-row"><span>Installation</span><strong>${esc(site(a.siteId)?.name)}</strong></div><div class="list-row"><span>Responsible</span><strong>${esc(a.assignee||'Unassigned')}</strong></div>${a.resolutionNote?`<div class="insight-line"><strong>Resolution note</strong><p>${esc(a.resolutionNote)}</p></div>`:''}<div class="form-footer">${editable&&a.status==='open'?`<button class="btn" data-action="ack" data-id="${a.id}">✓ Acknowledge</button>`:''}${editable&&a.status!=='resolved'?`<button class="btn" data-action="resolve" data-id="${a.id}">Resolve with note</button><button class="primary-btn" data-action="new-order" data-site="${a.siteId}" data-incident="${a.id}">＋ Create WO</button>`:''}<button class="outline-btn" data-action="open-site-flow" data-id="${a.siteId}">Energy view ↗</button></div></div>`);}
function siteDetail(id){const s=site(id);if(!s)return;const c=customer(s.customerId);openModal(s.name,`<div class="modal-body"><p>${esc(s.location)} · ${esc(s.vendor)} ${esc(s.model)}</p><div class="detail-grid"><div class="detail"><div class="detail-label">Capacity</div><div class="detail-value">${fmt(s.capacityKw)} kWp</div></div><div class="detail"><div class="detail-label">Production today</div><div class="detail-value">${fmt(s.energyTodayKwh)} kWh</div></div><div class="detail"><div class="detail-label">Battery</div><div class="detail-value">${s.batteryPct===null?'N/A':s.batteryPct+'%'}</div></div></div><div class="list-row"><span>Monitoring status</span>${badge(s.status)}</div><div class="list-row"><span>Inverter identifier</span><b class="mono">${esc(s.serial)}</b></div><div class="list-row"><span>Last seen</span><b>${datetime(s.lastSeen)}</b></div><div class="list-row"><span>Customer record</span><b>${esc(c?.name)}</b></div><div class="list-row"><span>Installed</span><b>${date(s.installationDate)}</b></div><div class="warning-box" style="margin-top:15px">Identitas, serial dan pengukuran adalah contoh simulasi. Gunakan API/vendor portal untuk data pelanggan nyata.</div><div class="form-footer"><button class="btn" data-action="new-order" data-site="${s.id}">Create work order</button><button class="primary-btn" data-action="open-site-flow" data-id="${s.id}">Open energy view ↗</button></div></div>`);}
function newOrder(siteId=S.siteId,incidentId=''){if(!can('owner','operator','technician'))return toast('Peran ini tidak memiliki izin membuat work order.',true);const due=new Date(Date.now()+86400000).toISOString().slice(0,10);openModal('Create new work order',`<form id="order-form"><div class="form-grid"><div class="form-field"><label for="order-site">Installation</label><select id="order-site" class="select" name="siteId" required>${siteOptions(siteId)}</select></div><div class="form-field"><label for="order-priority">Priority</label><select id="order-priority" class="select" name="priority"><option value="normal">Normal</option><option value="high" ${incidentId?'selected':''}>High</option><option value="critical">Critical</option></select></div><div class="form-field" style="grid-column:1/-1"><label for="order-title">Task title</label><input id="order-title" class="input" name="title" maxlength="140" value="${incidentId?'Inspeksi & validasi alarm':''}" placeholder="Contoh: Periksa gateway dan jaringan" required></div><div class="form-field"><label for="order-assignee">Assigned technician</label><select id="order-assignee" class="select" name="assignee"><option value="teknisi@properenergy.local">Teknisi Lapangan</option><option value="operator@properenergy.local">Operator Monitoring</option></select></div><div class="form-field"><label for="order-due">Due date</label><input type="date" id="order-due" class="input" name="dueAt" value="${due}" required></div><div class="form-field" style="grid-column:1/-1"><label for="order-notes">Technical notes</label><textarea id="order-notes" class="input" name="notes" rows="3" maxlength="600" placeholder="Periksa kondisi inverter, log vendor, koneksi Wi-Fi, dan dokumentasi."></textarea></div></div><input type="hidden" name="incidentId" value="${esc(incidentId)}"><div class="form-footer"><button type="button" class="btn" data-action="close">Cancel</button><button type="submit" class="primary-btn">Save work order ↗</button></div></form>`);}
function orderDetail(id){const o=S.data.orders.find(o=>o.id===id);if(!o)return;const canEdit=can('owner','operator','technician');openModal(`Work order · ${o.id}`,`<div class="modal-body"><h3>${esc(o.title)}</h3><p>${esc(site(o.siteId)?.name)} · due ${date(o.dueAt)}</p><div class="detail-grid"><div class="detail"><div class="detail-label">Priority</div>${badge(o.priority)}</div><div class="detail"><div class="detail-label">Status</div>${badge(o.status)}</div><div class="detail"><div class="detail-label">Responsible</div><strong style="font-size:10px">${esc(o.assignee)}</strong></div></div><div class="list-row"><span>Incident reference</span><b>${esc(o.incidentId||'Manual task')}</b></div><div class="list-row"><span>Created</span><b>${datetime(o.createdAt)}</b></div><div class="insight-line"><strong>Task instructions</strong><p>${esc(o.notes||'Belum ada catatan.')}</p></div>${o.resolution?`<div class="quote-banner"><strong>Outcome: </strong>${esc(o.resolution)}</div>`:''}${canEdit&&o.status!=='completed'&&o.status!=='cancelled'?`<div class="form-footer"><button class="btn" data-action="order-update" data-id="${o.id}" data-status="scheduled">Schedule</button><button class="btn" data-action="order-update" data-id="${o.id}" data-status="in_progress">Start</button><button class="primary-btn" data-action="order-complete" data-id="${o.id}">Complete ↗</button></div>`:''}</div>`);}
function completeOrder(id){openModal('Complete work order',`<form id="resolve-wo-form"><input type="hidden" name="id" value="${esc(id)}"><p class="muted-note">Masukkan tindakan yang benar-benar dikerjakan pada skenario simulasi. Status tidak dapat selesai tanpa catatan.</p><div class="form-field" style="margin-top:14px"><label for="resolution-text">Work completion note</label><textarea id="resolution-text" class="input" name="resolution" maxlength="600" rows="5" placeholder="Jelaskan verifikasi, tindakan, dan hasil uji..." required></textarea></div><div class="form-footer"><button type="button" data-action="close" class="btn">Cancel</button><button type="submit" class="primary-btn">Complete & log ↗</button></div></form>`);}
function resolveAlert(id){openModal('Resolve incident',`<form id="resolve-alert-form"><input type="hidden" name="id" value="${esc(id)}"><p class="muted-note">Penyelesaian wajib disertai catatan yang dapat diaudit.</p><div class="form-field" style="margin-top:14px"><label for="alert-resolution">Resolution evidence</label><textarea id="alert-resolution" class="input" name="note" maxlength="320" rows="4" placeholder="Masalah yang diverifikasi, tindakan, hasil..." required></textarea></div><div class="form-footer"><button type="button" data-action="close" class="btn">Cancel</button><button type="submit" class="primary-btn">Resolve incident ↗</button></div></form>`);}
function customerDetail(id){const c=customer(id);if(!c)return;const ns=S.data.notes.filter(n=>n.customerId===c.id),s=site(c.siteId);openModal(c.name,`<div class="modal-body"><div class="detail-grid"><div class="detail"><div class="detail-label">Service plan</div><b>${esc(c.servicePlan)}</b></div><div class="detail"><div class="detail-label">Segment</div><b>${esc(c.segment)}</b></div><div class="detail"><div class="detail-label">Installation</div><b>${esc(s.name)}</b></div></div><div class="list-row"><span>Contact</span><span>${esc(c.contact)}</span></div><div class="list-row"><span>System status</span>${badge(s.status)}</div><h3 style="margin-top:19px">Activity notes</h3>${ns.length?ns.map(n=>`<div class="insight-line"><p>${esc(n.body)}</p><div class="muted-note">${datetime(n.createdAt)} · ${esc(n.by)}</div></div>`).join(''):'<div class="empty"><strong>No notes yet</strong><p>Add an after-sales follow-up note.</p></div>'}${can('owner','operator','finance')?`<form id="customer-note-form"><input type="hidden" name="id" value="${c.id}"><div class="form-field"><label for="customer-note">Add care note</label><textarea id="customer-note" class="input" name="note" maxlength="800" rows="3" required placeholder="Catatan hasil follow-up pelanggan..."></textarea></div><div class="form-footer"><button type="submit" class="primary-btn">Save note ↗</button></div></form>`:''}</div>`);}
function simulateModal(){if(!can('owner','operator'))return toast('Gunakan akun Owner atau Operator untuk trigger demo.',true);openModal('Trigger a demo incident',`<form id="simulate-form"><p class="muted-note">Menciptakan alarm kritis buatan untuk mendemonstrasikan proses acknowledge → work order → closure. Tidak menyentuh inverter sesungguhnya.</p><div class="form-field" style="margin-top:14px"><label for="simulate-site">Choose demo installation</label><select class="select" id="simulate-site" name="siteId">${siteOptions('SITE-006')}</select></div><div class="form-footer"><button type="button" data-action="close" class="btn">Cancel</button><button type="submit" class="primary-btn">Create test alarm ↗</button></div></form>`);}
const TOUR=[{view:'overview',title:'01 · Operations at a glance',text:'Tunjukkan jumlah instalasi, produksi simulasi, jumlah alarm aktif dan masalah yang harus ditangani hari ini.'},{view:'fleet',title:'02 · Multi-brand fleet',text:'Buka satu tabel untuk instalasi Deye, Solis, Huawei, GoodWe, Sungrow, Growatt. Filter lokasi offline dan buka detail inverter.'},{view:'energy',title:'03 · Interactive energy flow',text:'Pilih Bintaro Residence, ubah dari siang ke malam, lihat PV, PLN, baterai dan beban rumah berubah. Pilih lokasi tanpa baterai untuk memastikan N/A.'},{view:'alerts',title:'04 · Proactive fault handling',text:'Dari alarm Serpong Garden → acknowledge → buat work order. Tekankan bahwa diagnosis belum berasal dari data live.'},{view:'orders',title:'05 · Technician dispatch',text:'Buka work order, ubah menjadi In Progress, lalu selesaikan dengan catatan pekerjaan. Data persisten di browser/server lokal.'},{view:'finance',title:'06 · Savings and after-sales',text:'Coba kalkulator tarif, self-consumption, O&M dan investasi; bedakan estimasi penghematan dari revenue after-sales.'},{view:'reports',title:'07 · Executive-ready reporting',text:'Ekspor CSV dan tunjukkan bahwa semua pekerjaan dapat ditelusuri, bukan sekadar animasi.'}];
function tour(step=0){S.tour=Math.max(0,Math.min(TOUR.length-1,step));const t=TOUR[S.tour];nav(t.view);openModal('Presentation walk-through',`<div class="tour-box"><div class="tour-step">STEP ${S.tour+1} / ${TOUR.length} · PROPER ENERGY LIVE DEMO</div><h3 style="font-size:24px;margin-top:12px">${esc(t.title)}</h3><p>${esc(t.text)}</p><div class="form-footer" style="justify-content:space-between"><button data-action="close" class="btn" style="border-color:#6b8d70;background:transparent;color:#cfe4d3">Tutup</button><div style="display:flex;gap:8px">${S.tour>0?'<button data-action="tour-prev" class="btn">← Back</button>':''}${S.tour<TOUR.length-1?'<button data-action="tour-next" class="primary-btn" style="background:#d9f19b;color:#1b3826">Next →</button>':'<button data-action="close" class="primary-btn" style="background:#d9f19b;color:#1b3826">Finish ✓</button>'}</div></div></div>`);}
function searchOpen(){if($('#command-overlay'))return;const root=document.createElement('div');root.id='command-overlay';root.className='search-overlay';root.innerHTML=`<div class="command-card"><div style="display:flex;align-items:center;gap:8px"><span style="font-size:25px;color:#78967e">⌕</span><input id="command-input" type="search" placeholder="Cari halaman, lokasi atau inverter..." autocomplete="off" aria-label="Pencarian cepat"/><button class="icon-action" data-action="search-close" aria-label="Tutup pencarian">×</button></div><div id="command-results" class="command-results"></div><div style="font-size:10px;color:#94a397;padding:12px">ESC to close · Search returns demo navigation and installation details</div></div>`;document.body.append(root);$('#command-input').focus();renderCommands('');}
function searchClose(){$('#command-overlay')?.remove();}
function renderCommands(q){const term=q.toLowerCase().trim();const navs=Object.entries(NAV).filter(([id,label])=>`${id} ${label}`.toLowerCase().includes(term)).slice(0,7).map(([id,label])=>`<button type="button" class="command-result" data-view="${id}"><span>▧ &nbsp; ${esc(label)}</span><span>Open ↗</span></button>`);const sites=S.data.sites.filter(s=>`${s.name} ${s.location} ${s.vendor}`.toLowerCase().includes(term)).slice(0,8).map(s=>`<button type="button" class="command-result" data-action="search-site" data-id="${s.id}"><span>☼ &nbsp; ${esc(s.name)} <small style="color:#889">${esc(s.vendor)}</small></span><span>${status(s.status)}</span></button>`);$('#command-results').innerHTML=navs.concat(sites).join('')||'<div class="empty">No matching location.</div>';}
const quote=x=>'"'+String(x??'').replaceAll('"','""').replace(/^[=+@\-\t\r]/,"'")+'"';
function downloadCsv(scope){const db=S.data;const name=`proper-energy-${scope}-demo.csv`;let rows=[];switch(scope){case 'sites':rows=[['ID','Location','Area','Vendor','Model','Capacity kWp','Power kW','Energy kWh','Status','Last seen'],...db.sites.map(s=>[s.id,s.name,s.location,s.vendor,s.model,s.capacityKw,s.powerKw,s.energyTodayKwh,s.status,s.lastSeen])];break;case 'alerts':rows=[['ID','Site','Severity','Issue','Status','Created','Resolved'],...db.alerts.map(a=>[a.id,site(a.siteId)?.name,a.severity,a.title,a.status,a.createdAt,a.resolvedAt])];break;case 'orders':rows=[['ID','Site','Title','Priority','Status','PIC','Due','Resolution'],...db.orders.map(o=>[o.id,site(o.siteId)?.name,o.title,o.priority,o.status,o.assignee,o.dueAt,o.resolution])];break;case 'customers':rows=[['ID','Name','Segment','Installation','Service plan'],...db.customers.map(c=>[c.id,c.name,c.segment,site(c.siteId)?.name,c.servicePlan])];break;case 'invoices':rows=[['ID','Customer','Service','Amount Rp','Status','Due'],...db.invoices.map(i=>[i.id,customer(i.customerId)?.name,i.description,i.amountRp,i.status,i.dueAt])];break;case 'activity':rows=[['Time','User','Action','Entity','Detail'],...db.activity.map(a=>[a.time,a.who,a.action,a.entity,a.description])];break;default:return toast('Jenis ekspor tidak ditemukan',true);}const blob=new Blob(['\ufeff'+rows.map(r=>r.map(quote).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast(`CSV ${scope} berhasil dibuat.`);}
async function ask(q){q=String(q||'').trim();if(!q)return;S.chat.push({who:'user',text:q});S.view='copilot';try{let ans=null;try{const activeSite=S.data?.sites?.find(x=>x.id===S.siteId);const invInfo=activeSite?`${activeSite.vendor} ${activeSite.model} (${activeSite.name})`:'Multi-Brand Fleet';const liveRes=await fetch('/api/chat',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({message:q,inverter:invInfo})});if(liveRes.ok){const liveData=await liveRes.json();if(liveData&&liveData.reply){ans={title:`Proper Energy AI Copilot (${liveData.model||'OpenRouter Cloud'})`,text:liveData.reply,next:'Rekomendasi dihitung berdasarkan standar IEEE 1547 & SNI PLTS.',confidence:'Model AI Cloud Aktif (OpenRouter Telemetry Engine)'};}}}catch(netErr){console.warn('API chat offline, using deterministic engine',netErr);}if(!ans){const res=await api('insights',{method:'POST',body:{question:q}});ans=res.answer;}S.chat.push({who:'ai',text:`${ans.title} — ${ans.text}`,next:ans.next,confidence:ans.confidence});}catch(e){S.chat.push({who:'ai',text:'Asisten demo gagal: '+e.message});}nav('copilot');const panel=$('#chat-output');if(panel)panel.scrollTop=panel.scrollHeight;}
async function clickAction(el){const a=el.dataset.action,id=el.dataset.id;switch(a){case 'tour':tour(0);break;case 'tour-next':tour(S.tour+1);break;case 'tour-prev':tour(S.tour-1);break;case 'site-detail':siteDetail(id);break;case 'alert-detail':alertDetail(id);break;case 'order-detail':orderDetail(id);break;case 'customer-detail':customerDetail(id);break;case 'simulate':simulateModal();break;case 'new-order':newOrder(el.dataset.site||S.siteId,el.dataset.incident||'');break;case 'ack':await act(()=>api(`alerts/${id}/ack`,{method:'POST',body:{}}),'Insiden diterima dan dicatat.');closeModal();break;case 'resolve':resolveAlert(id);break;case 'order-complete':completeOrder(id);break;case 'order-update':await act(()=>api(`orders/${id}`,{method:'PATCH',body:{status:el.dataset.status}}),'Status work order diperbarui.');closeModal();break;case 'mark-paid':if(!confirm('Tandai invoice demo ini sebagai lunas?'))break;await act(()=>api(`invoices/${id}`,{method:'PATCH',body:{status:'paid'}}),'Invoice demo ditandai lunas.');break;case 'open-site-flow':S.siteId=id;closeModal();nav('energy');break;case 'export':downloadCsv(el.dataset.scope);break;case 'print':window.print();break;case 'ask':await ask(el.dataset.question);break;case 'search-site':searchClose();siteDetail(id);break;case 'search-close':searchClose();break;case 'close':closeModal();break;case 'reset':if(!confirm('Kembalikan SELURUH data demo ke skenario awal? Semua perubahan lokal akan hilang.'))break;await act(()=>api('reset',{method:'POST',body:{}}),'Dataset demo berhasil di-reset.');break;case 'logout':sessionStorage.removeItem('pe_authenticated');sessionStorage.removeItem(SESSION);await api('logout',{method:'POST',body:{}});closeModal();S.data=null;S.user=null;S.chat=[];S.view='overview';$('#auth-screen').hidden=false;$('#login-password').value='Demo123!';break;default:break;}}
async function submitForm(form){const f=new FormData(form);switch(form.id){case 'login-form':{const err=$('#login-error');err.textContent='';const btn=form.querySelector('button[type="submit"]');btn.disabled=true;try{const res=await api('login',{method:'POST',body:{email:f.get('email'),password:f.get('password')}});sessionStorage.setItem('pe_authenticated','true');S.user=res.user;S.view='overview';await sync();$('#auth-screen').hidden=true;nav('overview');toast('Login berhasil. Selamat datang, '+(res.user?.display||res.user?.name||'Operator')+'.');}catch(e){err.textContent=e.message;}finally{btn.disabled=false;}break;}
 case 'simulate-form':{const id=f.get('siteId');closeModal();await act(()=>api('alerts/simulate',{method:'POST',body:{siteId:id}}),'Alarm simulasi dibuat.');nav('alerts');break;}
 case 'order-form':{const data={siteId:f.get('siteId'),title:f.get('title'),priority:f.get('priority'),assignee:f.get('assignee'),dueAt:new Date(f.get('dueAt')+'T16:00:00').toISOString(),notes:f.get('notes'),incidentId:f.get('incidentId')};closeModal();await act(()=>api('orders',{method:'POST',body:data}),'Work order tersimpan.');nav('orders');break;}
 case 'resolve-alert-form':{const id=f.get('id'),note=f.get('note');closeModal();await act(()=>api(`alerts/${id}/resolve`,{method:'POST',body:{note}}),'Insiden diselesaikan dengan catatan.');break;}
 case 'resolve-wo-form':{const id=f.get('id'),resolution=f.get('resolution');closeModal();await act(()=>api(`orders/${id}`,{method:'PATCH',body:{status:'completed',resolution}}),'Work order selesai dan tercatat.');break;}
 case 'customer-note-form':{const id=f.get('id'),note=f.get('note');closeModal();await act(()=>api(`customers/${id}/note`,{method:'POST',body:{note}}),'Catatan pelanggan disimpan.');break;}
 case 'finance-form':{const t=Number(f.get('tariff')),self=Number(f.get('self')),om=Number(f.get('cost')),capex=Number(f.get('capex'));if(![t,self,om,capex].every(Number.isFinite)||t<0||self<0||self>100||om<0||capex<0)return toast('Periksa rentang input kalkulator.',true);const monthly=sum(S.data.sites,x=>x.monthlyEnergyKwh),gross=monthly*(self/100)*t,net=gross-om,payback=net>0?capex/net/12:null;$('#finance-results').innerHTML=`<strong>Calculated scenario</strong><p>Gross saving <b>${money(gross)}/month</b> · after O&M <b>${money(net)}/month</b> · simple payback <b>${payback!==null?fmt(payback)+' years':'not viable at these assumptions'}</b>.</p><p class="muted-note">Simple payback excludes financing, battery replacement, degradation, taxes and other costs.</p>`;toast('Kalkulasi skenario diperbarui.');break;}
 case 'chat-form':{const q=f.get('question');form.reset();await ask(q);break;}
 case 'settings-form':{const body={tariffRp:Number(f.get('tariffRp')),monthlyOmRp:Number(f.get('monthlyOmRp')),alertSlaCriticalMin:Number(f.get('alertSlaCriticalMin'))};await act(()=>api('settings',{method:'PATCH',body}),'Pengaturan demo diperbarui.');break;}
 }}
function events(){document.addEventListener('click',async e=>{const action=e.target.closest('[data-action]'),view=e.target.closest('[data-view]'),hour=e.target.closest('[data-hour]'),period=e.target.closest('[data-period]');if(action){e.preventDefault();try{await clickAction(action);}catch(err){toast(err.message,true);}return;}if(view){e.preventDefault();searchClose();closeModal();nav(view.dataset.view);return;}if(hour){S.hour=hour.dataset.hour;render();return;}if(period){S.period=period.dataset.period;render();return;}});
 document.addEventListener('submit',async e=>{if(!['login-form','simulate-form','order-form','resolve-alert-form','resolve-wo-form','customer-note-form','finance-form','chat-form','settings-form'].includes(e.target.id))return;e.preventDefault();try{await submitForm(e.target);}catch(err){toast(err.message,true);}});
 document.addEventListener('change',e=>{if(e.target.id==='site-picker'){S.siteId=e.target.value;render();}if(e.target.id==='severity-filter'){S.severity=e.target.value;render();}if(e.target.dataset.filter==='status'){S.status=e.target.value;render();}});
 document.addEventListener('input',e=>{if(e.target.dataset.filter==='search'){const input=e.target,start=input.selectionStart;S.search=input.value;render();const newInput=$('[data-filter="search"]');if(newInput){newInput.focus();newInput.setSelectionRange(start,start);}}if(e.target.id==='command-input')renderCommands(e.target.value);});
 document.addEventListener('keydown',e=>{if(e.key==='Escape'){if($('#command-overlay'))searchClose();else closeModal();}if((e.key==='/'||e.key.toLowerCase()==='k'&&e.ctrlKey)&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName)){e.preventDefault();searchOpen();}});
 $('#global-search').addEventListener('click',searchOpen);
 $('#top-alert-button').addEventListener('click',()=>nav('alerts'));
 $('#tour-trigger').addEventListener('click',()=>tour(0));
 $('#start-tour-side').addEventListener('click',()=>tour(0));
 $('#logout-button').addEventListener('click',()=>clickAction({dataset:{action:'logout'}}));
 $('#side-profile').addEventListener('click',()=>nav('settings'));
 $('#modal-close').addEventListener('click',closeModal);
 $('#modal-backdrop').addEventListener('click',e=>{if(e.target.id==='modal-backdrop')closeModal();});
 $('#nav-backdrop').addEventListener('click',()=>{$('#sidebar').classList.remove('open');$('#nav-backdrop').hidden=true;});
 $('#mobile-menu').addEventListener('click',()=>{const open=$('#sidebar').classList.toggle('open');$('#nav-backdrop').hidden=!open;$('#mobile-menu').setAttribute('aria-expanded',String(open));});
 window.addEventListener('hashchange',()=>{if(S.data&&NAV[location.hash.slice(1)])nav(location.hash.slice(1));});
 const clock=()=>{$('#clock-label').textContent=new Intl.DateTimeFormat('id-ID',{weekday:'short',hour:'2-digit',minute:'2-digit',timeZone:'Asia/Jakarta'}).format(new Date())+' WIB';};clock();setInterval(clock,30000);
}
async function init(){events();await probe();if(sessionStorage.getItem('pe_authenticated')!=='true'){$('#auth-screen').hidden=false;return;}try{const m=await api('me');S.user=m.user;await sync();$('#auth-screen').hidden=true;}catch(e){sessionStorage.removeItem('pe_authenticated');$('#auth-screen').hidden=false;}}
init();
})();
